import{c as t,Z as e,Q as i,j as l,m as r,o as s}from"./chunks/framework.DOi4mjdC.js";const q=JSON.parse('{"title":"卜算子·咏梅","description":"","frontmatter":{"title":"卜算子·咏梅","author":"陆游","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/12.md","filePath":"books/shici/songci/12.md"}'),n={name:"books/shici/songci/12.md"};function h(c,a,u,p,d,_){const o=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="卜算子·咏梅" tabindex="-1">卜算子·咏梅 <a class="header-anchor" href="#卜算子·咏梅" aria-label="Permalink to &quot;卜算子·咏梅&quot;">​</a></h1><p><strong>[宋] <a href="/authors/luyou.html">陆游</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>驿外断桥边，寂寞开无主。已是黄昏独自愁，更着风和雨。</p><p>无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>卜算子：词牌名</li><li>驿：驿站</li><li>断桥：残破的桥</li><li>无主：无人过问</li><li>更着：又遭受</li><li>苦争春：苦苦与百花争春</li><li>一任：任凭</li><li>群芳：百花</li><li>妒：嫉妒</li><li>零落：凋谢</li><li>碾：轧碎</li><li>如故：依旧，仍然</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>在驿站外的断桥边，梅花寂寞地开放，无人过问。已经是黄昏时分，独自忧愁，又遭受着风雨的摧残。</p><p>梅花无意苦苦与百花争春，任凭百花去嫉妒。即使凋谢落地，被轧碎成泥尘，只有那清香依旧如故。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是陆游的代表作，以梅花自喻，表达了词人高洁不屈的品格和坚贞不渝的气节。</p><p>上片写梅花的孤独和艰难处境。&quot;驿外断桥边，寂寞开无主&quot;，写梅花生长在荒僻之地，无人欣赏。&quot;已是黄昏独自愁，更着风和雨&quot;，写梅花在黄昏时分独自忧愁，又遭受风雨的摧残。这里的梅花，正是词人自身的写照，暗示了词人在政治上的孤独和遭受的打击。</p><p>下片写梅花的高洁品格。&quot;无意苦争春，一任群芳妒&quot;，写梅花不与百花争艳，任凭百花嫉妒。这表现了词人不与世俗同流合污的高洁品格。&quot;零落成泥碾作尘，只有香如故&quot;，是全词的名句。即使梅花凋谢落地，被碾碎成泥尘，它的清香依旧不变。这表达了词人即使遭受打击、身处逆境，也绝不改变高洁品格的坚定信念。</p><p>全词托物言志，以梅花的高洁象征自己的品格，语言朴素，意境深远，是咏梅词中的千古绝唱。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>陆游</strong>（1125年－1210年），字务观，号放翁，南宋著名诗人。其诗多写爱国情怀，风格雄浑豪放，是南宋中兴四大诗人之一。</p><p><a href="/authors/luyou.html">查看作者详情 →</a></p></blockquote>',18)),s(o)])}const b=t(n,[["render",h]]);export{q as __pageData,b as default};
